INSERT INTO "_mocha_migrations" ("number","up_sql","down_sql","applied_at") VALUES(1,replace('\n-- Products table (Master Data)\nCREATE TABLE products (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  name TEXT NOT NULL,\n  price INTEGER NOT NULL,\n  stock INTEGER NOT NULL,\n  min_stock INTEGER NOT NULL,\n  default_method TEXT NOT NULL,\n  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP\n);\n\n-- Orders table\nCREATE TABLE orders (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  order_number TEXT NOT NULL,\n  client_name TEXT NOT NULL,\n  client_phone TEXT,\n  client_address TEXT,\n  notes TEXT,\n  total_amount INTEGER NOT NULL,\n  paid_amount INTEGER NOT NULL,\n  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP\n);\n\n-- Order items table\nCREATE TABLE order_items (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  order_id INTEGER NOT NULL,\n  product_id INTEGER,\n  product_name TEXT NOT NULL,\n  quantity INTEGER NOT NULL,\n  unit_price INTEGER NOT NULL,\n  discount INTEGER NOT NULL,\n  subtotal INTEGER NOT NULL,\n  method TEXT NOT NULL,\n  deadline_date DATE NOT NULL,\n  status_work TEXT,\n  status_send TEXT,\n  status_payment TEXT,\n  status_pickup TEXT,\n  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP\n);\n\n-- Expenses table\nCREATE TABLE expenses (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  expense_type TEXT NOT NULL,\n  description TEXT NOT NULL,\n  amount INTEGER NOT NULL,\n  expense_date DATE NOT NULL,\n  vendor_name TEXT,\n  order_id INTEGER,\n  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP\n);\n\n-- Store settings table\nCREATE TABLE store_settings (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  name TEXT NOT NULL,\n  address TEXT,\n  phone TEXT,\n  email TEXT,\n  instagram TEXT,\n  facebook TEXT,\n  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP\n);\n\n-- Create indexes for faster queries\nCREATE INDEX idx_orders_created_at ON orders(created_at);\nCREATE INDEX idx_order_items_order_id ON order_items(order_id);\nCREATE INDEX idx_order_items_deadline ON order_items(deadline_date);\nCREATE INDEX idx_expenses_date ON expenses(expense_date);\nCREATE INDEX idx_products_stock ON products(stock, min_stock);\n','\n',char(10)),replace('\nDROP INDEX idx_products_stock;\nDROP INDEX idx_expenses_date;\nDROP INDEX idx_order_items_deadline;\nDROP INDEX idx_order_items_order_id;\nDROP INDEX idx_orders_created_at;\nDROP TABLE store_settings;\nDROP TABLE expenses;\nDROP TABLE order_items;\nDROP TABLE orders;\nDROP TABLE products;\n','\n',char(10)),'2026-03-31 10:31:37');
