PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE _mocha_migrations (
number     INTEGER UNIQUE,
up_sql     TEXT NOT NULL,
down_sql   TEXT NOT NULL,
applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE products (
id INTEGER PRIMARY KEY AUTOINCREMENT,
name TEXT NOT NULL,
price INTEGER NOT NULL,
stock INTEGER NOT NULL,
min_stock INTEGER NOT NULL,
default_method TEXT NOT NULL,
created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
, user_id TEXT);
CREATE TABLE orders (
id INTEGER PRIMARY KEY AUTOINCREMENT,
order_number TEXT NOT NULL,
client_name TEXT NOT NULL,
client_phone TEXT,
client_address TEXT,
notes TEXT,
total_amount INTEGER NOT NULL,
paid_amount INTEGER NOT NULL,
created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
, discount INTEGER DEFAULT 0, user_id TEXT, branch_id INTEGER, pickup_status TEXT DEFAULT 'belum_diambil', pickup_date DATETIME, pickup_photo_key TEXT, payment_method TEXT);
CREATE TABLE order_items (
id INTEGER PRIMARY KEY AUTOINCREMENT,
order_id INTEGER NOT NULL,
product_id INTEGER,
product_name TEXT NOT NULL,
quantity INTEGER NOT NULL,
unit_price INTEGER NOT NULL,
discount INTEGER NOT NULL,
subtotal INTEGER NOT NULL,
method TEXT NOT NULL,
deadline_date DATE NOT NULL,
status_work TEXT,
status_send TEXT,
status_payment TEXT,
status_pickup TEXT,
created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
, user_id TEXT);
CREATE TABLE expenses (
id INTEGER PRIMARY KEY AUTOINCREMENT,
expense_type TEXT NOT NULL,
description TEXT NOT NULL,
amount INTEGER NOT NULL,
expense_date DATE NOT NULL,
vendor_name TEXT,
order_id INTEGER,
created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
, user_id TEXT);
CREATE TABLE store_settings (
id INTEGER PRIMARY KEY AUTOINCREMENT,
name TEXT NOT NULL,
address TEXT,
phone TEXT,
email TEXT,
instagram TEXT,
facebook TEXT,
created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
, user_id TEXT, admin_fee_qris REAL, admin_fee_va REAL, admin_fee_ewallet REAL, admin_fee_cc REAL);
CREATE TABLE branches (
id INTEGER PRIMARY KEY AUTOINCREMENT,
name TEXT NOT NULL,
address TEXT,
phone TEXT,
user_id TEXT,
created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE payment_records (
id INTEGER PRIMARY KEY AUTOINCREMENT,
order_id INTEGER NOT NULL,
amount INTEGER NOT NULL,
payment_method TEXT NOT NULL,
payment_type TEXT NOT NULL,
user_id TEXT,
created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE payment_gateway_settings (
id INTEGER PRIMARY KEY AUTOINCREMENT,
user_id TEXT NOT NULL,
pin_hash TEXT,
doku_client_id TEXT,
doku_secret_key TEXT,
doku_environment TEXT DEFAULT 'sandbox',
created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE doku_payments (
id INTEGER PRIMARY KEY AUTOINCREMENT,
order_id INTEGER NOT NULL,
invoice_number TEXT NOT NULL,
amount INTEGER NOT NULL,
admin_fee INTEGER NOT NULL,
total_amount INTEGER NOT NULL,
status TEXT DEFAULT 'pending',
doku_invoice_id TEXT,
payment_method TEXT,
user_id TEXT,
created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_orders_created_at ON orders(created_at);
CREATE INDEX idx_order_items_order_id ON order_items(order_id);
CREATE INDEX idx_order_items_deadline ON order_items(deadline_date);
CREATE INDEX idx_expenses_date ON expenses(expense_date);
CREATE INDEX idx_products_stock ON products(stock, min_stock);
CREATE INDEX idx_payment_records_order_id ON payment_records(order_id);
CREATE INDEX idx_payment_records_user_id ON payment_records(user_id);
